// Combinational circuit, time-independent (no $display calls, no $dumpfile).
// The synthesis tool should be able to infer a simple LUT2 (a short, flat
// combinational circuit).
module TopModule(input a, b, output q);
    wire w1 = a & b;
    wire w2 = ~(a | b);
    assign q = w1 | w2;
endmodule

